function dietFeedback(){const d=dialogBox('Discussions et propositions','<div class="discussion-filters"><button class="button secondary" data-feedback-filter="all">Tout</button><button class="button secondary" data-feedback-filter="unread">Non lus</button><button class="button secondary" data-feedback-filter="proposals">Propositions</button></div><div data-feedback-list></div>');d.classList.add('shared-feedback-dialog');function draw(filter='all'){const rows=shared.status.services.filter(info=>info.proposals.length||info.comments.length).filter(info=>filter==='all'||(filter==='unread'?unreadComments(info)>0:info.proposals.some(p=>p.status==='pending'))).sort((a,b)=>Number(unreadComments(b)>0)-Number(unreadComments(a)>0));d.querySelector('[data-feedback-list]').innerHTML=rows.map(info=>{const last=info.comments.at(-1),pending=info.proposals.filter(p=>p.status==='pending'),unread=unreadComments(info);return '<section class="shared-proposal-card"><h3>'+esc(discussionLabel(info))+'</h3>'+(last?'<p class="discussion-last">'+esc(last.message)+'</p><small>'+esc(last.name)+' · '+esc(roleLabel(last.role))+' · '+new Date(last.created_at).toLocaleString('fr-FR')+'</small>':'<p>Aucun message.</p>')+(unread?'<p class="discussion-unread">'+unread+' non lu'+(unread>1?'s':'')+'</p>':'')+'<div class="dialog-actions">'+button('Ouvrir la discussion','feedback-discussion',info.id)+(pending.length?button(pending.length+' proposition'+(pending.length>1?'s':'')+' en attente','feedback-service',info.id):'')+'</div></section>';}).join('')||'<p>Aucun échange dans cette sélection.</p>';d.querySelectorAll('[data-feedback-filter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.feedbackFilter===filter));}d.querySelectorAll('[data-feedback-filter]').forEach(b=>b.onclick=()=>draw(b.dataset.feedbackFilter));draw();}
