function dragComparison(payload,library){if(payload.rows)return payload.rows.map(r=>'<h3>'+esc(new Date(String(r.date).slice(0,10)+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'}))+' · '+(r.period==='lunch'?'Midi':'Soir')+'</h3><div class="proposal-comparison"><section><h3>Avant</h3><div class="service-cartouches">'+r.before.map(dishVisual).join('')+'</div></section><section><h3>Après</h3><div class="service-cartouches">'+r.after.map(dishVisual).join('')+'</div></section></div>').join('');const cell=id=>{const t=library.find(x=>x.id===id);return t?.components?.map(dishVisual).join('')||'<p class="muted">Créneau vide</p>';},label=(date,period)=>new Date(date+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})+' · '+(period==='lunch'?'Midi':'Soir'),rows=[{label:label(payload.sourceDate,payload.sourcePeriod),before:payload.sourceTemplateId,after:payload.action==='swap'?payload.targetTemplateId:null},{label:label(payload.date,payload.period),before:payload.targetTemplateId,after:payload.sourceTemplateId}];return rows.map(r=>'<h3>'+esc(r.label)+'</h3><div class="proposal-comparison"><section><h3>Avant</h3><div class="service-cartouches">'+cell(r.before)+'</div></section><section><h3>Après</h3><div class="service-cartouches">'+cell(r.after)+'</div></section></div>').join('');}
