document.addEventListener('click',e=>{if(!shared.user)return;if(e.target.closest('[data-shared-compose],[data-shared-service-proposal]'))return;if(shared.user.role==='diet'&&e.target.closest('.planned-card')&&!e.target.closest('[data-shared-action]')){e.preventDefault();e.stopImmediatePropagation();const day=e.target.closest('[data-drop-date]'),date=day.dataset.dropDate,period=day.dataset.dropPeriod,s=state.week.menu.days.find(x=>x.date===date)?.[period==='lunch'?'lunchService':'dinnerService'];if(s)window.openPlannedNutrition(s.plannedServiceId);}},true);
function changeReadKey(event,change){return 'paperchef:marker:'+shared.user.id+':'+event.id+':'+change.id;}
