window.addEventListener('click',event=>{if(!window.PaperChefShared?.user||window.PaperChefShared.user.role==='cook')return;const target=event.target.closest('[data-new-library-dish],[data-edit-dish-card],[data-dish-active],[data-service-trash],[data-service-duplicate],[data-compact-edit],[data-permanent-kind],[data-select-service-dish],[data-select-week-service],[data-dish-selection-action],[data-reset-week-selection],[data-library="new"],[data-library="edit"],[data-library="duplicate"],[data-library="archive"],[data-library="restore"],[data-library="delete"],#library-list [data-action="choose-slot"],[data-library="choose-slot"],[data-library="plan"]');if(target){event.preventDefault();event.stopImmediatePropagation();}},true);
